WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_1bd6c0faa693361e>
    <urn:graphragprov:unit:u_2692dc5609ff13f5>
    <urn:graphragprov:unit:u_6806d0b1dddb455b>
    <urn:graphragprov:unit:u_7dd333450b757e15>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
